package com.jadhavr.erp.academic.service;
import com.jadhavr.erp.academic.dto.AcademicDtos.*; import com.jadhavr.erp.academic.entity.*; import com.jadhavr.erp.academic.enums.*; import com.jadhavr.erp.academic.repository.*; import com.jadhavr.erp.auth.security.*; import com.jadhavr.erp.college.entity.*; import com.jadhavr.erp.college.repository.*; import com.jadhavr.erp.common.exception.*; import com.jadhavr.erp.department.entity.*; import com.jadhavr.erp.department.repository.*; import com.jadhavr.erp.staff.entity.*; import com.jadhavr.erp.staff.enums.*; import com.jadhavr.erp.staff.repository.*; import com.jadhavr.erp.student.entity.*; import com.jadhavr.erp.student.enums.*; import com.jadhavr.erp.student.repository.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class AcademicServiceImpl implements AcademicService {
 private final AcademicClassRepository classes; private final SectionRepository sections; private final SubjectRepository subjects; private final StudentSectionEnrollmentRepository enrollments; private final SubjectTeacherAssignmentRepository assignments; private final TimetableEntryRepository timetable; private final AttendanceSessionRepository sessions; private final AttendanceRecordRepository records; private final CollegeRepository colleges; private final DepartmentRepository departments; private final StaffProfileRepository staff; private final StudentProfileRepository students;
 public AcademicServiceImpl(AcademicClassRepository a,SectionRepository s,SubjectRepository su,StudentSectionEnrollmentRepository e,SubjectTeacherAssignmentRepository as,TimetableEntryRepository t,AttendanceSessionRepository se,AttendanceRecordRepository r,CollegeRepository c,DepartmentRepository d,StaffProfileRepository st,StudentProfileRepository sp){classes=a;sections=s;subjects=su;enrollments=e;assignments=as;timetable=t;sessions=se;records=r;colleges=c;departments=d;staff=st;students=sp;}
 public AcademicClass createClass(CreateClass r){ scope(r.collegeId(),r.departmentId()); College c=colleges.findById(r.collegeId()).orElseThrow(()->new ResourceNotFoundException("College not found")); Department d=departments.findById(r.departmentId()).orElseThrow(()->new ResourceNotFoundException("Department not found")); if(c.getStatus()!=CollegeStatus.ACTIVE||d.getStatus()!=DepartmentStatus.ACTIVE)throw new BadRequestException("College and department must be active"); String code=up(r.code()); if(classes.existsByCollegeIdAndDepartmentIdAndAcademicYearAndCodeIgnoreCase(c.getId(),d.getId(),r.academicYear(),code))throw new DuplicateResourceException("Class code already exists"); AcademicClass x=new AcademicClass();x.setCollege(c);x.setDepartment(d);x.setAcademicYear(r.academicYear());x.setName(r.name().trim());x.setCode(code);x.setDescription(r.description());return classes.save(x);}
 @Transactional(readOnly=true) public List<Map<String,Object>> classes(Long d){DepartmentScope access=departmentScope();return classes.findScoped(access.collegeId(),access.departmentIds(),access.allDepartments(),d).stream().filter(x->access.allows(x.getCollege().getId(),x.getDepartment().getId())).map(this::classView).toList();}
 public AcademicClass classStatus(Long id,boolean active){AcademicClass x=classes.findById(id).orElseThrow(()->new ResourceNotFoundException("Class not found"));scope(x.getCollege().getId(),x.getDepartment().getId());x.setStatus(active?AcademicStatus.ACTIVE:AcademicStatus.INACTIVE);return x;}
 public Section createSection(CreateSection r){AcademicClass c=classes.findById(r.academicClassId()).orElseThrow(()->new ResourceNotFoundException("Class not found"));scope(c.getCollege().getId(),c.getDepartment().getId());if(c.getStatus()!=AcademicStatus.ACTIVE)throw new BadRequestException("Class is inactive");String code=up(r.code());if(sections.existsByAcademicClassIdAndAcademicYearAndCodeIgnoreCase(c.getId(),r.academicYear(),code))throw new DuplicateResourceException("Section code already exists");Section x=new Section();x.setCollege(c.getCollege());x.setDepartment(c.getDepartment());x.setAcademicClass(c);x.setAcademicYear(r.academicYear());x.setName(r.name().trim());x.setCode(code);x.setCapacity(r.capacity());return sections.save(x);}
 @Transactional(readOnly=true) public List<Map<String,Object>> sections(Long c){DepartmentScope access=departmentScope();return sections.findScoped(access.collegeId(),access.departmentIds(),access.allDepartments(),c).stream().filter(x->access.allows(x.getCollege().getId(),x.getDepartment().getId())).map(this::sectionView).toList();}
 public Section assignClassTeacher(Long id,Assign r){Section x=section(id);StaffProfile t=staff.findById(r.staffProfileId()).orElseThrow(()->new ResourceNotFoundException("Staff not found"));same(x,t,StaffType.CLASS_TEACHER);x.setClassTeacher(t);return x;}
 public Map<String,Object> assignStudent(Long id,AssignStudent r){Section x=section(id);StudentProfile s=students.findById(r.studentProfileId()).orElseThrow(()->new ResourceNotFoundException("Student not found"));if(s.getStatus()!=StudentStatus.ACTIVE||!s.getCollege().getId().equals(x.getCollege().getId())||!s.getDepartment().getId().equals(x.getDepartment().getId()))throw new BadRequestException("Student must be active and belong to the section department");if(enrollments.existsByStudentIdAndAcademicYearAndStatus(s.getId(),x.getAcademicYear(),AcademicStatus.ACTIVE))throw new DuplicateResourceException("Student already enrolled for this academic year");if(enrollments.countBySectionIdAndStatus(id,AcademicStatus.ACTIVE)>=x.getCapacity())throw new BadRequestException("Section capacity reached");StudentSectionEnrollment e=new StudentSectionEnrollment();e.setStudent(s);e.setSection(x);e.setAcademicClass(x.getAcademicClass());e.setAcademicYear(x.getAcademicYear());e.setRollNumber(s.getRollNumber());StudentSectionEnrollment saved=enrollments.save(e);return Map.of("enrollmentId",saved.getId(),"studentProfileId",s.getId(),"sectionId",x.getId(),"division",x.getName(),"academicYear",x.getAcademicYear());}
 public Map<String,Object> createSubject(CreateSubject r){AcademicClass c=classes.findById(r.academicClassId()).orElseThrow(()->new ResourceNotFoundException("Class not found"));scope(c.getCollege().getId(),c.getDepartment().getId());if(c.getStatus()!=AcademicStatus.ACTIVE)throw new BadRequestException("Course year is inactive");String code=up(r.code());Optional<Subject> existing=subjects.findByAcademicClassIdAndAcademicYearAndCodeIgnoreCase(c.getId(),r.academicYear(),code);if(existing.isPresent()&&existing.get().getStatus()==SubjectStatus.ACTIVE)throw new DuplicateResourceException("Subject code already exists");Subject x=existing.orElseGet(Subject::new);x.setCollege(c.getCollege());x.setDepartment(c.getDepartment());x.setAcademicClass(c);x.setAcademicYear(r.academicYear());x.setName(r.name().trim());x.setCode(code);x.setDescription(r.description());x.setCredits(r.credits());x.setSubjectType(r.subjectType());x.setStatus(SubjectStatus.ACTIVE);Subject saved=subjects.save(x);return subjectView(saved);}
 public Map<String,Object> updateSubject(Long id,UpdateSubject r){Subject s=subjects.findById(id).orElseThrow(()->new ResourceNotFoundException("Subject not found"));scope(s.getCollege().getId(),s.getDepartment().getId());String code=up(r.code());if(subjects.existsByAcademicClassIdAndAcademicYearAndCodeIgnoreCase(s.getAcademicClass().getId(),s.getAcademicYear(),code)&&!s.getCode().equals(code))throw new DuplicateResourceException("Subject code already exists");s.setName(r.name().trim());s.setCode(code);s.setDescription(r.description());s.setCredits(r.credits());s.setSubjectType(r.subjectType());return subjectView(subjects.save(s));}
 public void deleteSubject(Long id){Subject s=subjects.findById(id).orElseThrow(()->new ResourceNotFoundException("Subject not found"));scope(s.getCollege().getId(),s.getDepartment().getId());assignments.findBySubjectIdAndStatus(id,AcademicStatus.ACTIVE).forEach(a->a.setStatus(AcademicStatus.INACTIVE));timetable.findBySubjectIdAndStatus(id,AcademicStatus.ACTIVE).forEach(t->t.setStatus(AcademicStatus.INACTIVE));s.setStatus(SubjectStatus.INACTIVE);subjects.save(s);}
 @Transactional(readOnly=true) public List<Map<String,Object>> subjects(Long c,Long d,String y){DepartmentScope access=departmentScope();return subjects.findScoped(access.collegeId(),access.departmentIds(),access.allDepartments(),SubjectStatus.ACTIVE,c,d).stream().filter(x->access.allows(x.getCollege().getId(),x.getDepartment().getId())).filter(x->y==null||y.equals(x.getAcademicClass().getYearName().name())).map(this::subjectView).toList();}
 public Map<String,Object> assignTeacher(Long id,Assign r){Subject s=subjects.findById(id).orElseThrow(()->new ResourceNotFoundException("Subject not found"));scope(s.getCollege().getId(),s.getDepartment().getId());StaffProfile t=staff.findById(r.staffProfileId()).orElseThrow(()->new ResourceNotFoundException("Staff not found"));if(t.getStatus()!=StaffStatus.ACTIVE)throw new BadRequestException("Staff must be active");Set<StaffType> teachingTypes=EnumSet.of(StaffType.TEACHER,StaffType.CLASS_TEACHER,StaffType.SUBJECT_TEACHER);if(!teachingTypes.contains(t.getStaffType()))throw new BadRequestException("Only teaching staff can be assigned to subjects; HOD accounts are not eligible");if(!t.getCollege().getId().equals(s.getCollege().getId())||!t.belongsToDepartment(s.getDepartment().getId()))throw new BadRequestException("Teacher must belong to the subject department");if(assignments.existsBySubjectIdAndTeacherIdAndStatus(id,r.staffProfileId(),AcademicStatus.ACTIVE))throw new DuplicateResourceException("Teacher is already assigned to this subject");SubjectTeacherAssignment a=new SubjectTeacherAssignment();a.setSubject(s);a.setTeacher(t);a.setAcademicYear(s.getAcademicYear());SubjectTeacherAssignment saved=assignments.save(a);return Map.<String,Object>of("id",saved.getId(),"subjectId",s.getId(),"subjectName",s.getName(),"subjectCode",s.getCode(),"teacherId",t.getId(),"teacherName",t.getFullName(),"academicYear",saved.getAcademicYear());}
 public void unassignTeacher(Long subjectId,Long teacherId){Subject s=subjects.findById(subjectId).orElseThrow(()->new ResourceNotFoundException("Subject not found"));scope(s.getCollege().getId(),s.getDepartment().getId());SubjectTeacherAssignment a=assignments.findBySubjectIdAndTeacherIdAndStatus(subjectId,teacherId,AcademicStatus.ACTIVE).orElseThrow(()->new ResourceNotFoundException("Assignment not found"));a.setStatus(AcademicStatus.INACTIVE);assignments.save(a);}
 public List<Map<String,Object>> listAssignments(Long teacherId,Long subjectId){DepartmentScope access=departmentScope();return assignments.findScoped(access.collegeId(),access.departmentIds(),access.allDepartments(),AcademicStatus.ACTIVE,teacherId,subjectId).stream().filter(a->access.allows(a.getSubject().getCollege().getId(),a.getSubject().getDepartment().getId())).map(a->Map.<String,Object>of("id",a.getId(),"subjectId",a.getSubject().getId(),"subjectName",a.getSubject().getName(),"subjectCode",a.getSubject().getCode(),"teacherId",a.getTeacher().getId(),"teacherName",a.getTeacher().getFullName(),"academicYear",a.getAcademicYear())).toList();}
 public TimetableEntry createTimetable(CreateTimetable r){Section s=section(r.sectionId());Subject u=subjects.findById(r.subjectId()).orElseThrow(()->new ResourceNotFoundException("Subject not found"));StaffProfile t=staff.findById(r.teacherId()).orElseThrow(()->new ResourceNotFoundException("Teacher not found"));same(s,t,StaffType.SUBJECT_TEACHER);if(!u.getAcademicClass().getId().equals(s.getAcademicClass().getId())||!r.endTime().isAfter(r.startTime()))throw new BadRequestException("Invalid subject or time range");if(!assignments.existsBySubjectIdAndTeacherIdAndStatus(u.getId(),t.getId(),AcademicStatus.ACTIVE))throw new BadRequestException("Teacher is not assigned to subject");if(timetable.hasClash(s.getId(),t.getId(),r.dayOfWeek(),r.startTime(),r.endTime()))throw new BadRequestException("Section or teacher timetable clash");TimetableEntry e=new TimetableEntry();e.setSection(s);e.setSubject(u);e.setTeacher(t);e.setDayOfWeek(r.dayOfWeek());e.setStartTime(r.startTime());e.setEndTime(r.endTime());e.setRoomNumber(r.roomNumber());return timetable.save(e);}
 @Transactional(readOnly=true) public List<TimetableEntry> timetable(Long id){Section s=section(id);return timetable.findBySectionIdAndStatusOrderByDayOfWeekAscStartTimeAsc(s.getId(),AcademicStatus.ACTIVE);}
 public AttendanceSession createAttendance(CreateAttendance r){if(!java.time.LocalDate.now().equals(r.attendanceDate()))throw new BadRequestException("Attendance can be created only for today's date");Section s=section(r.sectionId());Subject u=subjects.findById(r.subjectId()).orElseThrow(()->new ResourceNotFoundException("Subject not found"));StaffProfile teacher=currentStaff();if(!assignments.existsBySubjectIdAndTeacherIdAndStatus(u.getId(),teacher.getId(),AcademicStatus.ACTIVE))throw new AccessDeniedException("Teacher is not assigned to subject");AttendanceSession a=new AttendanceSession();a.setSection(s);a.setSubject(u);a.setTeacher(teacher);a.setAttendanceDate(r.attendanceDate());a.setTopic(r.topic());if(r.timetableEntryId()!=null)a.setTimetableEntry(timetable.findById(r.timetableEntryId()).orElseThrow(()->new ResourceNotFoundException("Timetable entry not found")));a=sessions.save(a);for(StudentSectionEnrollment e:enrollments.findBySectionIdAndStatus(s.getId(),AcademicStatus.ACTIVE)){AttendanceRecord ar=new AttendanceRecord();ar.setSession(a);ar.setStudent(e.getStudent());records.save(ar);}return a;}
 public AttendanceSession mark(Long id,Mark r){AttendanceSession s=session(id);requireAttendanceOwner(s);requireToday(s);if(s.getStatus()!=AttendanceSessionStatus.OPEN)throw new BadRequestException("Submitted attendance cannot be edited");for(MarkItem i:r.records()){if(i.status()!=AttendanceStatus.PRESENT&&i.status()!=AttendanceStatus.ABSENT)throw new BadRequestException("Attendance status must be PRESENT or ABSENT");AttendanceRecord a=records.findBySessionIdAndStudentId(id,i.studentProfileId()).orElseThrow(()->new BadRequestException("Student is not enrolled in this session"));a.setStatus(i.status());a.setRemarks(i.remarks());}return s;}
 public AttendanceSession submit(Long id){AttendanceSession s=session(id);requireAttendanceOwner(s);requireToday(s);if(s.getStatus()!=AttendanceSessionStatus.OPEN)throw new BadRequestException("Attendance already submitted");s.setStatus(AttendanceSessionStatus.SUBMITTED);return s;}
 @Transactional(readOnly=true) public Map<String,Object> attendanceSummary(Long id){StudentProfile student=students.findById(id).orElseThrow(()->new ResourceNotFoundException("Student not found"));if(SecurityUtils.hasRole("STUDENT")){if(!student.getId().equals(currentStudent().getId()))throw new AccessDeniedException("Cannot view another student's attendance");}else scope(student.getCollege().getId(),student.getDepartment().getId());List<AttendanceRecord> a=records.findByStudentId(id).stream().filter(x->x.getSession().getStatus()==AttendanceSessionStatus.SUBMITTED).toList();long p=a.stream().filter(x->x.getStatus()==AttendanceStatus.PRESENT||x.getStatus()==AttendanceStatus.LATE).count();return Map.of("studentProfileId",id,"totalSessions",a.size(),"presentSessions",p,"percentage",a.isEmpty()?0.0:p*100.0/a.size());}
 @Transactional(readOnly=true) public List<StudentRosterItem> eligibleStudents(Long academicClassId){AcademicClass c=classes.findById(academicClassId).orElseThrow(()->new ResourceNotFoundException("Class not found"));scope(c.getCollege().getId(),c.getDepartment().getId());return students.findEligibleForAcademicYear(c.getDepartment().getId(),StudentStatus.ACTIVE,c.getAcademicYear(),AcademicStatus.ACTIVE).stream().map(this::roster).toList();}
 @Transactional(readOnly=true) public List<StudentRosterItem> sectionStudents(Long sectionId){Section s=section(sectionId);return enrollments.findBySectionIdAndStatus(s.getId(),AcademicStatus.ACTIVE).stream().map(e->roster(e.getStudent())).toList();}
 @Transactional(readOnly=true) public Map<String,Object> classTeacherRoster(){StaffProfile teacher=currentStaff();Section section=sections.findByClassTeacherIdAndStatus(teacher.getId(),SectionStatus.ACTIVE).stream().findFirst().orElseThrow(()->new ResourceNotFoundException("No active class is assigned to you"));return classDetails(section);}
 @Transactional(readOnly=true) public Map<String,Object> studentClass(){StudentProfile student=currentStudent();StudentSectionEnrollment enrollment=enrollments.findFirstByStudentAndStatus(student,AcademicStatus.ACTIVE).orElseThrow(()->new ResourceNotFoundException("You have not been assigned to a class yet"));return studentClassDetails(enrollment.getSection());}
 private Map<String,Object> classView(AcademicClass c){Map<String,Object> view=new LinkedHashMap<>();view.put("id",c.getId());view.put("college",Map.of("id",c.getCollege().getId(),"name",c.getCollege().getName()));view.put("department",Map.of("id",c.getDepartment().getId(),"name",c.getDepartment().getName()));view.put("academicYear",c.getAcademicYear());view.put("yearName",c.getYearName().name());view.put("name",c.getName());view.put("code",c.getCode());view.put("description",c.getDescription());view.put("status",c.getStatus());return view;}
 private Map<String,Object> sectionView(Section s){Map<String,Object> view=new LinkedHashMap<>();view.put("id",s.getId());view.put("academicClass",classView(s.getAcademicClass()));view.put("academicYear",s.getAcademicYear());view.put("name",s.getName());view.put("code",s.getCode());view.put("capacity",s.getCapacity());view.put("status",s.getStatus());if(s.getClassTeacher()!=null)view.put("classTeacher",Map.of("id",s.getClassTeacher().getId(),"fullName",s.getClassTeacher().getFullName()));return view;}
 private Map<String,Object> subjectView(Subject s){Map<String,Object> view=new LinkedHashMap<>();view.put("id",s.getId());view.put("academicClass",classView(s.getAcademicClass()));view.put("academicYear",s.getAcademicYear());view.put("name",s.getName());view.put("code",s.getCode());view.put("description",s.getDescription());view.put("credits",s.getCredits());view.put("subjectType",s.getSubjectType()!=null?s.getSubjectType().name():null);view.put("status",s.getStatus());return view;}
 private StudentRosterItem roster(StudentProfile s){return new StudentRosterItem(s.getId(),s.getAdmissionNumber(),s.getRollNumber(),s.getFullName(),s.getEmail(),s.getPhone());}
 private Map<String,Object> classDetails(Section s){return Map.of("sectionId",s.getId(),"className",s.getAcademicClass().getName(),"courseYear",s.getAcademicClass().getYearName().name(),"division",s.getName(),"divisionCode",s.getCode(),"department",s.getDepartment().getName(),"academicYear",s.getAcademicYear(),"classTeacher",s.getClassTeacher()==null?"Not assigned":s.getClassTeacher().getFullName(),"students",sectionStudents(s.getId()));} private Map<String,Object> studentClassDetails(Section s){return Map.of("sectionId",s.getId(),"className",s.getAcademicClass().getName(),"courseYear",s.getAcademicClass().getYearName().name(),"division",s.getName(),"divisionCode",s.getCode(),"department",s.getDepartment().getName(),"academicYear",s.getAcademicYear(),"classTeacher",s.getClassTeacher()==null?"Not assigned":s.getClassTeacher().getFullName(),"students",enrollments.findBySectionIdAndStatus(s.getId(),AcademicStatus.ACTIVE).stream().map(e->roster(e.getStudent())).toList());} private Section section(Long id){Section x=sections.findById(id).orElseThrow(()->new ResourceNotFoundException("Section not found"));scope(x.getCollege().getId(),x.getDepartment().getId());return x;} private AttendanceSession session(Long id){AttendanceSession s=sessions.findById(id).orElseThrow(()->new ResourceNotFoundException("Attendance session not found"));scope(s.getSection().getCollege().getId(),s.getSection().getDepartment().getId());return s;} private void requireAttendanceOwner(AttendanceSession s){StaffProfile current=currentStaff();boolean assigned=s.getTeacher()!=null&&s.getTeacher().getId().equals(current.getId());boolean classTeacher=s.getSection().getClassTeacher()!=null&&s.getSection().getClassTeacher().getId().equals(current.getId());if(!assigned&&!classTeacher)throw new AccessDeniedException("Attendance session is not assigned to you");} private void requireToday(AttendanceSession s){if(!java.time.LocalDate.now().equals(s.getAttendanceDate()))throw new BadRequestException("Attendance can be entered only for today's date");} private StaffProfile currentStaff(){return staff.findByUserId(SecurityUtils.requireCurrentUser().getId()).orElseThrow(()->new AccessDeniedException("Staff profile required"));} private StudentProfile currentStudent(){return students.findByUserId(SecurityUtils.requireCurrentUser().getId()).orElseThrow(()->new AccessDeniedException("Student profile required"));}
 private void same(Section s,StaffProfile t,StaffType type){same(s.getCollege().getId(),s.getDepartment().getId(),t,type);} private void same(Long c,Long d,StaffProfile t,StaffType type){if(t.getStaffType()!=type||!t.getCollege().getId().equals(c)||t.getDepartment()==null||!t.getDepartment().getId().equals(d))throw new BadRequestException("Teacher type, college or department does not match");}
 private void scope(Long c,Long d){if(!visible(c,d))throw new AccessDeniedException("Academic resource is outside your scope");} private boolean visible(Long c,Long d){CustomUserDetails u=SecurityUtils.requireCurrentUser();if(!c.equals(u.getCollegeId()))return false;if(SecurityUtils.isPrincipal())return true;if(SecurityUtils.hasRole("HOD"))return staff.findByUserId(u.getId()).map(x->x.belongsToDepartment(d)).orElse(false);if(SecurityUtils.hasRole("CLASS_TEACHER")||SecurityUtils.hasRole("SUBJECT_TEACHER"))return staff.findByUserId(u.getId()).map(x->x.belongsToDepartment(d)).orElse(false);return false;} private DepartmentScope departmentScope(){CustomUserDetails user=SecurityUtils.requireCurrentUser();if(SecurityUtils.isPrincipal())return new DepartmentScope(user.getCollegeId(),Set.of(-1L),true);if(!(SecurityUtils.hasRole("HOD")||SecurityUtils.hasRole("CLASS_TEACHER")||SecurityUtils.hasRole("SUBJECT_TEACHER")))return new DepartmentScope(user.getCollegeId(),Set.of(-1L),false);Set<Long> departmentIds=staff.findByUserId(user.getId()).map(profile->profile.getDepartments().stream().map(Department::getId).collect(java.util.stream.Collectors.toCollection(LinkedHashSet::new))).orElseGet(LinkedHashSet::new);return new DepartmentScope(user.getCollegeId(),departmentIds.isEmpty()?Set.of(-1L):departmentIds,false);} private record DepartmentScope(Long collegeId,Collection<Long> departmentIds,boolean allDepartments){boolean allows(Long candidateCollegeId,Long candidateDepartmentId){return Objects.equals(collegeId,candidateCollegeId)&&(allDepartments||departmentIds.contains(candidateDepartmentId));}} private String up(String s){return s.trim().toUpperCase(Locale.ROOT);}
}
